# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  def tenant_lens_receipt(id:, company_id:, body:)
    {
      "id" => id, "company_id" => company_id, "actor_type" => "User", "actor_id" => 5,
      "operation" => "create_entry", "key" => "same-key", "fingerprint" => body,
      "status" => 201, "body" => body, "created_at" => Time.utc(2026, 10, 1, 12)
    }
  end

  it "keeps two companies' receipts with the same key apart through load and export" do
    store = described_class.new(connection: ActiveRecord::Base.connection)
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: {
        "entries" => [], "reservations" => [], "invoice_operations" => [], "entry_audits" => [],
        "idempotency_records" => [
          tenant_lens_receipt(id: 1, company_id: 100, body: '{"id": 1,  "b":2}'),
          tenant_lens_receipt(id: 2, company_id: 200, body: '{"id":9,"a":1}')
        ]
      }
    )

    # "The entry API's idempotency receipts, keyed by tenant."
    store.load_checkpoint(checkpoint)

    stored = ActiveRecord::Base.connection.select_rows(
      "SELECT company_id, body FROM idempotency_records ORDER BY company_id"
    )
    expect(stored).to eq([[100, '{"id": 1,  "b":2}'], [200, '{"id":9,"a":1}']])
    exported = store.export_checkpoint
    expect(exported.digest["idempotency_records"].keys).to contain_exactly(100, 200)
    expect(exported.digest).to eq(checkpoint.digest)
  end
end

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  def tenant_lens_cross_entry_row(id:, company_id:)
    {
      "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1,
      "agent_id" => nil, "work_date" => Date.new(2026, 10, 1), "duration" => 60.0, "note" => "",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
      "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
      "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
      "created_at" => Time.utc(2026, 10, 1, 12), "updated_at" => Time.utc(2026, 10, 1, 12)
    }
  end

  it "refuses an audit row attached to another company's entry and leaves the tables unchanged" do
    connection = ActiveRecord::Base.connection
    connection.execute(<<~SQL.squish)
      INSERT INTO entries (id, company_id, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (500, 300, 1, 1, '2026-09-01', 15, 'unbilled', now(), now())
    SQL
    baseline = connection.select_rows("SELECT id, company_id FROM entries ORDER BY id")
    expect(baseline).to eq([[500, 300]])

    cross_company_audit = {
      "id" => 1, "company_id" => 200, "entry_id" => 10, "actor_type" => "User", "actor_id" => 5,
      "actor_name" => nil, "action" => "create", "before" => nil, "after" => { "duration" => 60.0 },
      "entry_created_at" => Time.utc(2026, 10, 1, 12), "created_at" => Time.utc(2026, 10, 1, 12)
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: {
        "entries" => [tenant_lens_cross_entry_row(id: 10, company_id: 100)], "reservations" => [],
        "invoice_operations" => [], "entry_audits" => [cross_company_audit], "idempotency_records" => []
      }
    )

    expect { described_class.new(connection: connection).load_checkpoint(checkpoint) }.to raise_error(StandardError)

    expect(connection.select_rows("SELECT id, company_id FROM entries ORDER BY id")).to eq(baseline)
    expect(connection.select_value("SELECT count(*) FROM entry_audits")).to eq(0)
  end
end

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  it "refuses a lower checkpoint version and names the entries table and the company" do
    connection = ActiveRecord::Base.connection
    connection.execute(<<~SQL.squish)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (10, 777, 5, 1, 1, '2026-10-01', 60, 'unbilled', now(), now())
    SQL
    expect(connection.select_rows("SELECT id, company_id, version FROM entries")).to eq([[10, 777, 5]])

    older_entry = {
      "id" => 10, "company_id" => 777, "version" => 3, "project_id" => 1, "user_id" => 1,
      "agent_id" => nil, "work_date" => Date.new(2026, 10, 1), "duration" => 60.0, "note" => "",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
      "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
      "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
      "created_at" => Time.utc(2026, 10, 1, 12), "updated_at" => Time.utc(2026, 10, 1, 12)
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: {
        "entries" => [older_entry], "reservations" => [], "invoice_operations" => [],
        "entry_audits" => [], "idempotency_records" => []
      }
    )

    # "A load refuses any entry whose current version in the store is higher than its version in the checkpoint."
    expect { described_class.new(connection: connection).load_checkpoint(checkpoint) }
      .to raise_error(/entries.*777|777.*entries/m)
    expect(connection.select_rows("SELECT id, company_id, version FROM entries")).to eq([[10, 777, 5]])
  end
end
